WITH warehouse_inventory AS ( SELECT w.w_warehouse_id, w.w_city, w.w_state, w.w_country, SUM(i.inv_quantity_on_hand) AS total_qty, COUNT(DISTINCT i.inv_item_sk) AS distinct_items, AVG(i.inv_quantity_on_hand) AS avg_qty FROM inventory i JOIN warehouse w ON i.inv_warehouse_sk = w.w_warehouse_sk WHERE i.inv_quantity_on_hand > 0 GROUP BY w.w_warehouse_id, w.w_city, w.w_state, w.w_country ) SELECT wi.w_warehouse_id, wi.w_city, wi.w_state, wi.w_country, wi.total_qty, wi.distinct_items, wi.avg_qty, (SELECT COUNT(*) FROM customer c JOIN customer_address ca ON c.c_current_addr_sk = ca.ca_address_sk WHERE ca.ca_state = wi.w_state) AS cust_count_in_state, (SELECT COUNT(*) FROM call_center cc WHERE cc.cc_state = wi.w_state AND cc.cc_manager = 'Bob Belcher') AS cc_bob_manager_count, RANK() OVER (ORDER BY wi.total_qty DESC) AS warehouse_rank FROM warehouse_inventory wi WHERE wi.total_qty > 1000 ORDER BY wi.total_qty DESC LIMIT 10
